"""Build the offline guide from reviewed Unity frames and actual game evidence."""
from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[1];GALLERY=ROOT/'Design/LevelAuthoring/AircraftSeasons';REVIEW=GALLERY/'GroundReview/G08'
def image(name,label):
    assert (REVIEW/(name+'.png')).exists()
    return f'<figure><button class="picture" data-image="GroundReview/G08/{name}.png" aria-label="Збільшити: {html.escape(label)}"><img src="GroundReview/G08/{name}.png" alt="{html.escape(label)}" loading="lazy"></button><figcaption>{html.escape(label)}</figcaption></figure>'
def compare(before,after,label):
    return f'<article><h3>{label}</h3><div class="compare"><img src="GroundReview/G08/{after}.png" alt="Після фактичного руху"><img class="before" src="GroundReview/G08/{before}.png" alt="Щойно встановлені намети"><span class="line"></span></div><label class="slider">Щойно встановлено ← <input type="range" min="0" max="100" value="50" aria-label="Порівняти поверхню: {label}"> → Після руху</label></article>'
seasons=[('spring','Весна'),('summer','Літо'),('autumn','Осінь'),('winter','Зима')]
season_cards=''.join(image(s,label) for s,label in seasons)
empty=''.join(image(s+'-empty',label+' — ще немає наметів; лише сітка розміщення') for s,label in [('spring','Весна'),('rain','Літній дощ'),('winter','Зима')])
used=compare('spring-detail','spring-used','Суха трава й утворення стежки')+image('rain-used','Дощ: витоптані мокрі ділянки після проходів')+compare('winter-detail','winter-used','Сніг і поступове ущільнення маршруту')
movies=''
for s,label in seasons+[('rain','Літній дощ')]:
    proof=json.loads((GALLERY/'GroundVerification'/(s+'-motion.json')).read_text(encoding='utf-8'));frames=proof['capture']['frames'];assert frames[-1]['surfaceSteps']>frames[0]['surfaceSteps']
    movies+=f'<article><h3>{label}</h3><video controls playsinline preload="metadata" src="GroundMotion/{s}.mp4"></video><p>Кроки під час запису: {frames[0]["surfaceSteps"]} → {frames[-1]["surfaceSteps"]}. Звичайний темп гри; відео без звукової доріжки.</p></article>'
content='''<!doctype html><html lang="uk"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>QuietCamp — жива земля й обростання</title>
<style>:root{color-scheme:light;--ink:#29352b;--paper:#f3f0e6;--accent:#385d3c}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:17px/1.6 system-ui,sans-serif}main{max-width:1160px;margin:auto;padding:30px 20px}nav{display:flex;gap:20px;flex-wrap:wrap}a{color:var(--accent)}h1{font-size:clamp(30px,5vw,48px);line-height:1.15}h2{margin-top:48px}.lead{max-width:820px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px}article,figure{margin:0}img,video{display:block;width:100%;border-radius:12px}figcaption{padding:9px 0}.picture{width:100%;border:0;padding:0;background:none;cursor:zoom-in}.note{padding:18px;border-left:4px solid #779164;background:#e5e9da}.compare{position:relative;overflow:hidden;border-radius:12px;aspect-ratio:1}.compare img{position:absolute;inset:0}.before{clip-path:inset(0 50% 0 0)}.line{position:absolute;top:0;bottom:0;left:50%;width:2px;background:white}.slider{display:flex;align-items:center;gap:8px;font-size:13px}.slider input{flex:1;min-width:60px;accent-color:var(--accent)}.steps li{padding:5px 0}dialog{padding:18px;border:0;max-width:95vw;background:var(--paper);border-radius:12px}dialog::backdrop{background:#142014dd}dialog img{max-height:82vh;max-width:90vw;width:auto}dialog button{float:right;padding:8px 16px}small{color:#52634f}details{margin-top:20px}@media(max-width:700px){.grid{grid-template-columns:1fr}main{padding:20px 14px}.slider{font-size:12px}}</style>
<main><nav><a href="../index.html">Довідка майстерні</a><a href="index.html">Попередня сезонна галерея</a><a href="#surface">Поверхня</a><a href="#growth">Обростання</a><a href="#motion">Гра в русі</a></nav>
<h1>Земля змінюється від життя табору</h1><p class="lead">До розміщення наметів поле має траву, листя або сніг. Сітка позначає місце для гри. Намет приминає покрив своєю основою; мешканці прокладають стежки власними кроками. Волога посилює багно, а снігопад поступово засипає старі сліди.</p>
<p class="note">Кадри нижче отримані в Unity, з сімома циклами перегляду й виправлень. «Після руху» показує <strong>600 секунд прискореної симуляції дозволених маршрутів</strong> у preview. Відео внизу записані зі звичайної ігрової камери без прискорення. Натисніть на картинку, щоб збільшити.</p>
<h2>Одна історія — чотири сезони</h2><div class="grid">SEASONS</div>
<h2 id="surface">До встановлення наметів</h2><p>Оголених прямокутників і намальованих майбутніх маршрутів немає. Короткий покрив розміщений природними групами; земля має переходи відтінків, мох і дрібне каміння.</p><div class="grid">EMPTY</div>
<h2>Після використання табору</h2><p>Перетягніть розділювач. Стежки з’являються лише там, де пройшли мешканці; спільна частина маршруту зношується сильніше. Вологі ділянки поступово темнішають і отримують дрібні нерівності та відблиски калюж. Снігові сліди ущільнюються й засипаються опадами.</p><div class="grid">USED</div>
<h2 id="growth">Обростити літак або інший старий об’єкт</h2><ol class="steps"><li>Відкрийте рівень у майстерні й виберіть декоративний об’єкт у Scene View.</li><li>Відкрийте <strong>QuietCamp → Інструменти → Старіння моделей</strong>.</li><li>У розділі <strong>Обростання природою</strong> оберіть матеріал основи, траву, папороть або витку зелень.</li><li>Задайте густоту, розмір, вологість і ділянки: затінені поверхні, основа або верх.</li><li>Натисніть <strong>Обростити вибраний об’єкт</strong>. Огляньте через ігрову камеру. Ctrl+Z скасовує дію.</li><li>Збережіть чернетку. Повторне застосування замінює лише обростання цього об’єкта. Рослини залишаються окремим редагованим декором і слідують за власником із рівномірним масштабом.</li></ol><p>Мох враховує матеріал, орієнтацію, близькість землі й оцінку затінення від крон та сусідніх деталей. Зима приховує листя; маска моху та старіння узгоджуються з сезоном.</p>
<h2 id="motion">Перевірка у звичайній грі</h2><div class="grid">MOVIES</div>
<details><summary>Перевірки та межі</summary><p>131 EditMode тестів: правила всіх 100 пазлів, історичні збереження, сезони, поверхня й обростання. П’ять тестових запусків: фактичний рух, лічильник кроків, три рівні якості, звук, рішення пазла, незмінний прогрес та відновлена чернетка.</p><p>Стан зносу належить поточній сцені; при повторному відкритті рівня починається нова симуляція. Калюжі й заглиблення — стилізоване візуальне наближення без фізики рідини та зміни колізій Terrain. Для власників із нерівномірним масштабом рослини залишаються окремими — після переміщення застосуйте обростання повторно. FPS телефону не вимірювався.</p><p><a href="GroundVerification/editmode-results.json">Результати тестів</a> · <a href="GroundVerification/ground-review.json">Сім циклів перегляду</a> · <a href="GroundVerification/motion-preservation.json">Збереження прогресу та чернетки</a></p></details>
<small>QuietCamp · нативні кадри 2026-10-14 · офлайн-довідка</small></main><dialog id="zoom"><button id="close">Закрити</button><img alt="Збільшений нативний кадр"></dialog>
<script>document.querySelectorAll('.slider input').forEach(input=>input.addEventListener('input',()=>{let a=input.closest('article');a.querySelector('.before').style.clipPath=`inset(0 ${100-input.value}% 0 0)`;a.querySelector('.line').style.left=input.value+'%'}));let dialog=document.querySelector('#zoom');document.querySelectorAll('[data-image]').forEach(button=>button.addEventListener('click',()=>{dialog.querySelector('img').src=button.dataset.image;dialog.querySelector('img').alt=button.querySelector('img').alt;dialog.showModal()}));document.querySelector('#close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});</script></html>'''
for key,value in [('SEASONS',season_cards),('EMPTY',empty),('USED',used),('MOVIES',movies)]:content=content.replace(key,value)
(GALLERY/'surface.html').write_text(content,encoding='utf-8');print('Built offline ground guide with 14 reviewed native frames, comparisons and five actual-game videos')
